rule YARA_CobaltStrike_Generic {
    meta:
        description = "Detects generic Cobalt Strike beacon patterns in memory or files"
        author = "SOC Team"
        confidence = "medium"
        false_positives = "Packed .NET assemblies, legitimate Microsoft updates"
        remediation = "Whitelist known-good hashes, refine entropy and import checks"
    strings:
        $a = { 60 00 6D 00 73 00 68 00 65 00 6C 00 6C 00 } // "msiexec" wide
        $b = "CryptEncrypt" wide
        $c = "LoadLibrary" wide
        $entropy = 7.8
    condition:
        uint16(0) == 0x5A4D and ($a or ($b and $c)) and entropy > $entropy
}

